using System.Security.Cryptography;using System.Text;using System.Text.Json;using System.Text.RegularExpressions;using CommanderOwnerConsent;
namespace CommanderOwnerAcceptance;
internal static class Program
{
    private static string phase="preflight";private static bool effect,privateWrite,keyOpened;
    internal static long Now=>DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
    internal static async Task<int> Main(string[] args)
    {
        try
        {
            if(args.SequenceEqual(new[]{"--selftest"}))return ProbeQA.Run();
            if(args.SequenceEqual(new[]{"--diagnose"})){var t=WindowsGuard.Inspect();Print("DIAGNOSTIC_ONLY",w=>{w.WriteBoolean("elevated",t.Elevated);w.WriteBoolean("interactiveOwnerSession",t.SessionId>0);w.WriteBoolean("authorityOpened",false);w.WriteBoolean("privateKeyOpened",false);w.WriteBoolean("taskOrConsentStarted",false);});return 0;}
            ConsentCore.Need(args.Length==1&&args[0] is "--prepare" or "--approve-compose" or "--exchange-verify","PROBE_EXACT_MODE");
            var elevated=args[0]=="--approve-compose";var token=WindowsGuard.Inspect();
            if(elevated)ConsentCore.Need(token.Elevated&&token.ElevationType==2&&token.Administrator&&token.IntegrityRid>=12288&&token.SessionId>0,"PROBE_REAL_OWNER_UAC_REQUIRED");
            else ConsentCore.Need(!token.Elevated&&!token.Administrator&&token.IntegrityRid is >=8192 and <12288&&token.SessionId>0,"PROBE_ORDINARY_OWNER_REQUIRED");
            using var authority=ProbeAuthority.Load(elevated);using var cancellation=new CancellationTokenSource(TimeSpan.FromSeconds(180));
            if(args[0]=="--prepare")await Prepare(authority,cancellation.Token);else if(elevated)await Approve(authority,cancellation.Token);else await Verify(authority,cancellation.Token);return 0;
        }
        catch(Exception e)
        {
            var code=e is ConsentFault?e.Message:e is OperationCanceledException?"PROBE_CANCELLED_RECONCILE_NO_RETRY":e is UnauthorizedAccessException?"PROBE_ACCESS_DENIED":e is JsonException or FormatException?"PROBE_INVALID_INPUT":e is FileNotFoundException or DirectoryNotFoundException?"PROBE_PROTECTED_ENROLLMENT_NOT_READY":e is IOException?"PROBE_IO_UNCERTAIN_NO_RETRY":"PROBE_UNAVAILABLE_NO_RETRY";
            var receipt=ProbeCrypto.Json(w=>{w.WriteString("status","STOP_RECONCILE_NO_RETRY");w.WriteString("code",code);w.WriteString("phase",phase);w.WriteBoolean("externalEffectMayHaveOccurred",effect);w.WriteBoolean("privateKeyOpened",keyOpened);w.WriteBoolean("ownedChildCleanupUncertain",ProbeIO.CleanupUncertain);w.WriteBoolean("automaticRetryAllowed",false);});
            if(privateWrite){try{ProbeIO.WritePrivate("failure.json",receipt,WindowsGuard.Inspect().Sid);}catch{}}
            Console.Error.WriteLine(Encoding.UTF8.GetString(receipt));return 2;
        }
    }
    private static void Print(string status,Action<Utf8JsonWriter>? extra=null)=>Console.WriteLine(Encoding.UTF8.GetString(ProbeCrypto.Json(w=>{w.WriteString("status",status);extra?.Invoke(w);w.WriteBoolean("automaticRetryAllowed",false);})));
    private static byte[] Rpc(string id,string action,Action<Utf8JsonWriter> arguments)=>ProbeCrypto.Json(w=>{w.WriteNumber("version",1);w.WriteString("id",id);w.WriteString("action",action);w.WritePropertyName("arguments");w.WriteStartObject();arguments(w);w.WriteEndObject();});
    private static async Task Prepare(ProbeAuthority a,CancellationToken cancel)
    {
        phase="prepare-private-admission";a.Revalidate();ProbeIO.NewPrivate(a.OwnerSid);privateWrite=true;var verifier=ConsentCore.B64(RandomNumberGenerator.GetBytes(32));var state=ConsentCore.B64(RandomNumberGenerator.GetBytes(32));var id=Guid.NewGuid().ToString("D");
        var seed=ProbeCrypto.Json(w=>{w.WriteString("schema","RC_OWNER_PROBE_SEED_V1");w.WriteString("ownerSid",a.OwnerSid);w.WriteNumber("session",a.Session);w.WriteNumber("createdAtMs",Now);w.WriteString("verifier",verifier);w.WriteString("state",state);w.WriteString("beginRpcId",id);w.WriteString("nativePolicySha256",ProbeAuthority.Hex(a.NativeBytes));w.WriteString("oauthPolicySha256",ProbeAuthority.Hex(a.OAuthBytes));});ProbeIO.WritePrivate("seed.json",seed,a.OwnerSid);
        var request=Rpc(id,"authorize",w=>{w.WriteString("phase","begin");w.WritePropertyName("request");w.WriteStartObject();w.WriteString("response_type","code");w.WriteString("client_id",ProbeAuthority.Client);w.WriteString("redirect_uri",ProbeAuthority.Redirect);w.WriteString("resource",ProbeAuthority.Resource);w.WriteString("code_challenge_method","S256");w.WriteString("code_challenge",ConsentCore.Digest(Encoding.ASCII.GetBytes(verifier)));w.WriteString("state",state);w.WriteString("grant_policy_id","selftest");w.WriteEndObject();});phase="authorize-begin-once";effect=true;using var response=ConsentCore.Strict(await ProbeIO.Rpc(a,request,cancel));var r=response.RootElement;ConsentCore.Fields(r,"status","requestId","requestDigest","expiresAtMs","reusedExisting","ownerNativeConsentRequired");var rid=Opaque(r,"requestId");var digest=Opaque(r,"requestDigest");var expires=r.GetProperty("expiresAtMs").GetInt64();ConsentCore.Need(expires>Now&&expires<=Now+120000&&r.GetProperty("ownerNativeConsentRequired").GetBoolean(),"PROBE_BEGIN_RESPONSE");
        var prepared=ProbeCrypto.Json(w=>{w.WriteString("schema","RC_OWNER_PROBE_PREPARED_V1");w.WriteString("seedSha256",ProbeAuthority.Hex(seed));w.WriteString("requestId",rid);w.WriteString("requestDigest",digest);w.WriteNumber("expiresAtMs",expires);});ProbeIO.WritePrivate("prepared.json",prepared,a.OwnerSid);Print("PREPARED_SELFTEST_ONLY",w=>{w.WriteString("requestId",rid);w.WriteString("requestDigest",digest);});
    }
    private sealed class Inputs:IDisposable
    {
        private readonly FileStream seedFile,preparedFile;internal readonly JsonDocument Seed,Prepared;internal readonly byte[] SeedBytes,PreparedBytes;internal string RequestId=>ConsentCore.Text(Prepared.RootElement,"requestId");internal string Digest=>ConsentCore.Text(Prepared.RootElement,"requestDigest");internal string Verifier=>ConsentCore.Text(Seed.RootElement,"verifier");internal string State=>ConsentCore.Text(Seed.RootElement,"state");internal string Binding=>ProbeAuthority.Hex(SeedBytes.Concat(PreparedBytes).ToArray());
        internal Inputs(ProbeAuthority a)
        {seedFile=ProbeIO.ReadPrivate("seed.json",a.OwnerSid);try{preparedFile=ProbeIO.ReadPrivate("prepared.json",a.OwnerSid);SeedBytes=WindowsGuard.Read(seedFile);PreparedBytes=WindowsGuard.Read(preparedFile);Seed=ConsentCore.Strict(SeedBytes);Prepared=ConsentCore.Strict(PreparedBytes);ValidateInputs(a,Seed.RootElement,Prepared.RootElement,ProbeAuthority.Hex(SeedBytes),Now);}catch{seedFile.Dispose();throw;}}
        public void Dispose(){Seed.Dispose();Prepared.Dispose();preparedFile.Dispose();seedFile.Dispose();}
    }
    internal static void ValidateInputs(ProbeAuthority a,JsonElement s,JsonElement p,string seedHash,long now)
    {
        ConsentCore.Fields(s,"schema","ownerSid","session","createdAtMs","verifier","state","beginRpcId","nativePolicySha256","oauthPolicySha256");ConsentCore.Fields(p,"schema","seedSha256","requestId","requestDigest","expiresAtMs");ConsentCore.Need(ConsentCore.Text(s,"schema")=="RC_OWNER_PROBE_SEED_V1"&&ConsentCore.Text(p,"schema")=="RC_OWNER_PROBE_PREPARED_V1"&&ConsentCore.Text(s,"ownerSid")==a.OwnerSid&&s.GetProperty("session").GetInt32()==a.Session&&ConsentCore.Text(s,"nativePolicySha256")==ProbeAuthority.Hex(a.NativeBytes)&&ConsentCore.Text(s,"oauthPolicySha256")==ProbeAuthority.Hex(a.OAuthBytes)&&ConsentCore.Text(p,"seedSha256")==seedHash,"PROBE_PRIVATE_INPUT_POLICY_BINDING");var created=s.GetProperty("createdAtMs").GetInt64();var expires=p.GetProperty("expiresAtMs").GetInt64();ConsentCore.Need(created<=now&&now-created<150000&&expires>now&&expires<=created+150000&&Regex.IsMatch(ConsentCore.Text(s,"verifier",128),"^[A-Za-z0-9_-]{43}$")&&Regex.IsMatch(ConsentCore.Text(s,"state",128),"^[A-Za-z0-9_-]{43}$"),"PROBE_PRIVATE_INPUT_LIFETIME");Opaque(p,"requestId");Opaque(p,"requestDigest");}
    private static string Opaque(JsonElement e,string name){var s=ConsentCore.Text(e,name,43);ConsentCore.Need(Regex.IsMatch(s,"^[A-Za-z0-9_-]{43}$"),"PROBE_OPAQUE_ID");return s;}
    private static async Task Approve(ProbeAuthority a,CancellationToken cancel)
    {
        // This mode writes no file under G:, including errors. Owner-controlled
        // input is held read-only and checked against protected pending bytes.
        phase="approve-validate-held-input";using var input=new Inputs(a);using var pending=WindowsGuard.OpenProtected(Path.Combine(a.StateRoot,"pending",input.RequestId+".json"),32768);var pendingBytes=WindowsGuard.Read(pending);var approved=ConsentCore.ValidatePending(pendingBytes,a.Native.RootElement,input.RequestId,Now);using var pd=ConsentCore.Strict(pendingBytes);var bound=pd.RootElement.GetProperty("bound");ConsentCore.Need(approved.RequestDigest==input.Digest&&ConsentCore.Text(bound,"challenge")==ConsentCore.Digest(Encoding.ASCII.GetBytes(input.Verifier))&&ConsentCore.Text(bound,"state")==input.State,"PROBE_ACTUAL_PENDING_BINDING");
        ProbeIO.NewProtected(a);ProbeIO.WriteProtected("approve.intent.json",ProbeCrypto.Json(w=>{w.WriteString("schema","RC_OWNER_PROBE_APPROVE_INTENT_V1");w.WriteString("requestId",input.RequestId);w.WriteString("requestDigest",input.Digest);w.WriteString("inputBindingSha256",input.Binding);w.WriteNumber("createdAtMs",Now);}),a);
        phase="human-native-consent-once";effect=true;await ProbeIO.Consent(a,input.RequestId,cancel);a.Revalidate();var fresh=ConsentCore.ValidatePending(WindowsGuard.Read(pending),a.Native.RootElement,input.RequestId,Now);using var receipt=WindowsGuard.OpenProtected(Path.Combine(a.StateRoot,"receipts",input.RequestId+".json"),32768);var rb=WindowsGuard.Read(receipt);using(var rd=ConsentCore.Strict(rb)){if(rd.RootElement.TryGetProperty("status",out _)){ProbeIO.WriteProtected("denied.json",ProbeCrypto.Json(w=>{w.WriteString("status","OWNER_DENIED_OR_TIMEOUT_NO_REPLAY");w.WriteString("requestId",input.RequestId);}),a);throw new ConsentFault("PROBE_OWNER_DENIED_OR_TIMEOUT");}}a.VerifyConsent(rb,fresh,Now);
        phase="fixed-selftest-client-assertion";using var keyFile=WindowsGuard.OpenProtected(Path.Combine(a.StateRoot,"selftest-client-key.pk8"),4096,true);var secret=WindowsGuard.Read(keyFile);keyOpened=true;string assertion;var issued=Now;try{using var key=ECDsa.Create();key.ImportPkcs8PrivateKey(secret,out var read);ConsentCore.Need(read==secret.Length,"PROBE_SELFTEST_KEY_FORMAT");a.DemandClientPrivate(key);assertion=ProbeCrypto.Assertion(key,issued);}finally{CryptographicOperations.ZeroMemory(secret);}a.Revalidate();
        ProbeIO.WriteProtected("assertion.json",ProbeCrypto.Json(w=>{w.WriteString("schema","RC_OWNER_PROBE_FIXED_ASSERTION_V1");w.WriteString("requestId",input.RequestId);w.WriteString("requestDigest",input.Digest);w.WriteString("inputBindingSha256",input.Binding);w.WriteString("nativePolicySha256",ProbeAuthority.Hex(a.NativeBytes));w.WriteString("oauthPolicySha256",ProbeAuthority.Hex(a.OAuthBytes));w.WriteNumber("issuedAtMs",issued);w.WriteNumber("expiresAtMs",issued/1000*1000+60000);w.WriteString("assertion",assertion);}),a);Print("HUMAN_CONSENT_AND_FIXED_ASSERTION_READY",w=>{w.WriteString("requestId",input.RequestId);w.WriteString("requestDigest",input.Digest);});
    }
    private static async Task Verify(ProbeAuthority a,CancellationToken cancel)
    {
        phase="ordinary-verify-intent";using var input=new Inputs(a);privateWrite=true;var completeId=Guid.NewGuid().ToString("D");var exchangeId=Guid.NewGuid().ToString("D");var stateId=Guid.NewGuid().ToString("D");ProbeIO.WritePrivate("verify.intent.json",ProbeCrypto.Json(w=>{w.WriteString("requestId",input.RequestId);w.WriteString("inputBindingSha256",input.Binding);w.WriteString("completeRpcId",completeId);w.WriteString("exchangeRpcId",exchangeId);w.WriteString("stateRpcId",stateId);}),a.OwnerSid);
        phase="readonly-wait-for-owner-assertion";var until=Now+90000;while(!File.Exists(Path.Combine(a.AcceptanceRoot,"assertion.json"))){ConsentCore.Need(Now<until,"PROBE_OWNER_ASSERTION_WAIT_EXPIRED");ConsentCore.Need(!File.Exists(Path.Combine(a.AcceptanceRoot,"denied.json")),"PROBE_OWNER_DENIED_OR_TIMEOUT");await Task.Delay(250,cancel);}
        a.Revalidate();using var assertionFile=WindowsGuard.OpenProtected(Path.Combine(a.AcceptanceRoot,"assertion.json"),32768);using var package=ConsentCore.Strict(WindowsGuard.Read(assertionFile));var ap=package.RootElement;ConsentCore.Fields(ap,"schema","requestId","requestDigest","inputBindingSha256","nativePolicySha256","oauthPolicySha256","issuedAtMs","expiresAtMs","assertion");ConsentCore.Need(ConsentCore.Text(ap,"schema")=="RC_OWNER_PROBE_FIXED_ASSERTION_V1"&&ConsentCore.Text(ap,"requestId")==input.RequestId&&ConsentCore.Text(ap,"requestDigest")==input.Digest&&ConsentCore.Text(ap,"inputBindingSha256")==input.Binding&&ConsentCore.Text(ap,"nativePolicySha256")==ProbeAuthority.Hex(a.NativeBytes)&&ConsentCore.Text(ap,"oauthPolicySha256")==ProbeAuthority.Hex(a.OAuthBytes)&&ap.GetProperty("issuedAtMs").GetInt64()<=Now&&ap.GetProperty("expiresAtMs").GetInt64()>Now,"PROBE_ASSERTION_PACKAGE_BINDING");var assertion=ConsentCore.Text(ap,"assertion",8192);using(var clientPublic=ProbeCrypto.PublicClient(a.OAuth.RootElement))ProbeCrypto.VerifyAssertion(assertion,clientPublic,Now);
        ValidateInputs(a,input.Seed.RootElement,input.Prepared.RootElement,ProbeAuthority.Hex(input.SeedBytes),Now);phase="ordinary-authorize-complete-once";ProbeIO.WritePrivate("complete.intent.json",Intent(input,completeId),a.OwnerSid);effect=true;using var completed=ConsentCore.Strict(await ProbeIO.Rpc(a,Rpc(completeId,"authorize",w=>{w.WriteString("phase","complete");w.WriteString("requestId",input.RequestId);}),cancel));var c=completed.RootElement;ConsentCore.Fields(c,"status","requestId","code","state","redirectUri","iss");ConsentCore.Need(ConsentCore.Text(c,"status")=="CODE_ISSUED"&&ConsentCore.Text(c,"requestId")==input.RequestId&&ConsentCore.Text(c,"state")==input.State&&ConsentCore.Text(c,"redirectUri")==ProbeAuthority.Redirect&&ConsentCore.Text(c,"iss")==ProbeAuthority.Issuer,"PROBE_AUTHORIZATION_CODE_BINDING");var code=Opaque(c,"code");
        phase="ordinary-exchange-once";ProbeIO.WritePrivate("exchange.intent.json",Intent(input,exchangeId),a.OwnerSid);using var exchange=ConsentCore.Strict(await ProbeIO.Rpc(a,Rpc(exchangeId,"exchange",w=>{w.WriteString("grant_type","authorization_code");w.WriteString("code",code);w.WriteString("client_id",ProbeAuthority.Client);w.WriteString("redirect_uri",ProbeAuthority.Redirect);w.WriteString("resource",ProbeAuthority.Resource);w.WriteString("code_verifier",input.Verifier);w.WriteString("client_assertion_type","urn:ietf:params:oauth:client-assertion-type:jwt-bearer");w.WriteString("client_assertion",assertion);}),cancel));var t=exchange.RootElement;ConsentCore.Fields(t,"access_token","token_type","expires_in","stateEnvelope","refreshTokenIssued");ConsentCore.Need(ConsentCore.Text(t,"token_type")=="Bearer"&&t.GetProperty("expires_in").GetInt32()==300&&!t.GetProperty("refreshTokenIssued").GetBoolean(),"PROBE_TOKEN_RESPONSE_BINDING");var token=ConsentCore.Text(t,"access_token",8192);var grant="grant:"+Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(input.RequestId))).ToLowerInvariant()[..32];var epoch=ConsentCore.Text(a.Native.RootElement,"enrollmentEpoch");ProbeCrypto.VerifyToken(token,a.IssuerPublic,epoch,grant,Now);var first=ProbeCrypto.VerifyState(t.GetProperty("stateEnvelope"),a.IssuerPublic,epoch,grant,Now,0);
        phase="fresh-grant-state-once";ProbeIO.WritePrivate("state.intent.json",Intent(input,stateId),a.OwnerSid);using var state=ConsentCore.Strict(await ProbeIO.Rpc(a,Rpc(stateId,"state",w=>w.WriteString("grantId",grant)),cancel));ConsentCore.Fields(state.RootElement,"stateEnvelope");var sequence=ProbeCrypto.VerifyState(state.RootElement.GetProperty("stateEnvelope"),a.IssuerPublic,epoch,grant,Now,first);a.Revalidate();
        var proof=ProbeCrypto.Json(w=>{w.WriteString("schema","RC_OWNER_SELFTEST_E2E_RECEIPT_V1");w.WriteString("status","PASS_ACTUAL_ORDINARY_OWNER_NO_PROJECT_E2E");w.WriteString("requestId",input.RequestId);w.WriteString("requestDigest",input.Digest);w.WriteString("grantId",grant);w.WriteString("tokenSha256",ProbeAuthority.Hex(Encoding.UTF8.GetBytes(token)));w.WriteNumber("freshStateSequence",sequence);w.WriteBoolean("tokenPersistedOrPrinted",false);w.WriteBoolean("projectAuthority",false);w.WriteBoolean("automaticRetryAllowed",false);});ProbeIO.WritePrivate("result.json",proof,a.OwnerSid);Console.WriteLine(Encoding.UTF8.GetString(proof));
    }
    private static byte[] Intent(Inputs input,string id)=>ProbeCrypto.Json(w=>{w.WriteString("requestId",input.RequestId);w.WriteString("rpcId",id);w.WriteNumber("createdAtMs",Now);w.WriteBoolean("automaticRetryAllowed",false);});
}
